package glitch

import data.glitch_lib

hardcoded_password_keywords := {"password", "pass", "pwd", "secret", "token"}

# Check if the value is a hardcoded string, excluding variable references or dynamic calls
is_hardcoded_value(value) {
    value.ir_type == "String"
    value.value != ""
}

is_hardcoded_value(value) {
    value.ir_type == "Hash"
}

is_hardcoded_value(value) {
    value.ir_type == "Array"
}

# Check for known default credentials patterns
check_default_credentials(value) {
    value.ir_type == "String"
    regex.match("(?i)(admin:admin|root:password|scott:tiger)", value.value)
}

# Check for Base64 encoded strings (heuristic)
is_base64_encoded(value) {
    value.ir_type == "String"
    regex.match("^[A-Za-z0-9+/]+={0,2}$", value.value)
    count(value.value) >= 20
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check attribute name for password-related keywords
    contains(attr.name, hardcoded_password_keywords[_])

    # Check if the value is hardcoded
    is_hardcoded_value(attr.value)

    # Ensure it's not a variable reference or dynamic function call
    not attr.value.ir_type == "VariableReference"

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password in configuration - Use of static credentials exposes the system to credential theft. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for default credentials
    check_default_credentials(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Default or well-known credentials used - Avoid using default credentials in production. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for Base64 encoded secrets
    is_base64_encoded(attr.value)
    contains(attr.name, hardcoded_password_keywords[_])

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Base64 encoded hard-coded secret - Encoding is not encryption and can be easily reversed. (CWE-259)"
    }
}

