package glitch

import data.glitch_lib

password_attributes := {"password", "pass", "pwd", "secret", "token"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == password_attributes[_]

    attr.value.ir_type == "String"
    not is_secure_secret(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded password detected in IaC configuration. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name == password_attributes[_]

    attr.value.ir_type == "String"
    is_base64_encoded(attr.value.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded Base64-encoded password detected in IaC configuration. (CWE-259)"
    }
}

is_secure_secret(value) {
    # Check for dynamic secret retrieval patterns
    regex.match("(?i).*{{.*secret.*}}.*", value)
} else {
    regex.match("(?i).*vault.*", value)
} else {
    regex.match("(?i).*ssm.*parameter.*", value)
} else {
    regex.match("(?i).*get_secret.*", value)
} else {
    regex.match("(?i).*reference.*keyvault.*", value)
}

is_base64_encoded(value) {
    # Simple Base64 pattern check
    regex.match("^[A-Za-z0-9+/]*={0,2}$", value)
    not regex.match("^[A-Za-z0-9]+$", value)
}

